const {test}=require('node:test');const assert=require('node:assert/strict');const fs=require('node:fs');const vm=require('node:vm');const {makeSeed}=require('./seed.js');
function app(initial=null,fail=false,startMode='personal',initialLearning=null,seedPersonal=true){if(initial===null&&startMode==='personal'&&seedPersonal)initial=JSON.stringify(makeSeed());const nodes=new Map(),store=new Map(initial===null?[]:[['codedfemale-product-studio-v1',initial]]);store.set('codedfemale-product-studio-mode-v1',startMode);if(initialLearning!==null)store.set('codedfemale-product-studio-learning-v1',initialLearning);const node=()=>({innerHTML:'',textContent:'',dataset:{},showModal(){this.open=true},close(){this.open=false},click(){},setAttribute(){},focus(){}});const doc={body:{dataset:{}},querySelector(s){if(!nodes.has(s))nodes.set(s,node());return nodes.get(s)},querySelectorAll:()=>[],addEventListener(){},createElement:node};const c=vm.createContext({document:doc,localStorage:{getItem:k=>store.get(k)||null,setItem(k,v){if(fail)throw Error('quota');store.set(k,v)}},console,Date,Blob,TextEncoder,URL:class extends URL{static createObjectURL(){return ''}static revokeObjectURL(){}},crypto:require('node:crypto').webcrypto,setTimeout:()=>0,clearTimeout(){},window:{scrollTo(){}}});vm.runInContext(fs.readFileSync(__dirname+'/seed.js','utf8')+'\n'+fs.readFileSync(__dirname+'/learning.js','utf8')+'\n'+fs.readFileSync(__dirname+'/practice.js','utf8')+'\n'+fs.readFileSync(__dirname+'/team-tools.js','utf8')+'\n'+fs.readFileSync(__dirname+'/refinements.js','utf8')+'\n'+fs.readFileSync(__dirname+'/clarity.js','utf8')+'\n'+fs.readFileSync(__dirname+'/personal-calendar.js','utf8')+'\n'+fs.readFileSync(__dirname+'/estimation.js','utf8')+'\n'+fs.readFileSync(__dirname+'/efficiency.js','utf8')+'\n'+fs.readFileSync(__dirname+'/app.js','utf8'),c);return {c,run:s=>vm.runInContext(s,c),store,nodes};}
test('seed dates are local and weekday sessions cover one two-week Sprint',()=>{const s=makeSeed('2026-11-04');assert.equal(s.settings.start,'2026-11-02');assert.equal(s.settings.end,'2026-11-13');assert.equal(s.events.filter(e=>e.title==='Daily Scrum').length,10);for(const e of s.events){assert.ok(e.date>=s.settings.start&&e.date<=s.settings.end);assert.ok(![0,6].includes(new Date(e.date+'T12:00:00').getDay()))}assert.equal(s.items.filter(i=>i.sprint).length,5)});
test('backup validation rejects malformed records and duplicate identifiers',()=>{const a=app();assert.equal(a.run('validate(state)'),true);for(const mutation of ["s.items[0].id=s.items[1].id","s.events[0].date='2026-02-30'","s.events[0].time='24:00'","s.events[0].duration='0'","s.events[0].duration='900'","s.items[0].points='-1'","s.items[0].sprint='yes'","s.settings.scene='evil'","s.events[0].id='bad identifier'","s.settings.end='2000-01-01'","s.outcomes[0].title=s.outcomes[1].title","s.records[0].kind='unknown'"]){assert.throws(()=>a.run(`(()=>{const s=JSON.parse(JSON.stringify(state));${mutation};validate(s)})()`))}});
test('moving cards preserves work and saves Sprint membership',()=>{const a=app();a.run("move('P-106','In progress')");let s=JSON.parse(a.store.get('codedfemale-product-studio-v1'));assert.equal(s.items.find(i=>i.id==='P-106').sprint,true);assert.equal(s.items.find(i=>i.id==='P-106').status,'In progress');a.run("move('P-106','Backlog')");s=JSON.parse(a.store.get('codedfemale-product-studio-v1'));assert.equal(s.items.length,11);assert.equal(s.items.find(i=>i.id==='P-106').sprint,false)});
test('saved workspace reloads and user strings render as text',()=>{const s=makeSeed('2026-11-02');s.settings.name='My team';s.items[0].title='<img src=x onerror=alert(1)>';const a=app(JSON.stringify(s));assert.equal(a.run('state.settings.name'),'My team');const html=a.run('backlog()');assert.ok(html.includes('&lt;img'));assert.ok(!html.includes('<img src=x'));});
test('corrupt storage remains untouched until explicit recovery',()=>{const a=app('{broken');assert.equal(a.run('recovery'),true);a.run('save()');assert.equal(a.store.get('codedfemale-product-studio-v1'),'{broken');assert.equal(a.nodes.get('#editor').open,true)});
test('storage failure leaves data in memory and exposes backup warning',()=>{const a=app(null,true);a.run("move('P-101','In progress')");assert.equal(a.run('storageOK'),false);assert.equal(a.run("state.items[0].status"),'In progress');assert.match(a.nodes.get('#save-state').textContent,/Not saved/)});
test('calendar export includes every event, escapes text and folds UTF-8 lines',()=>{const a=app();a.run("state.events[0].title='Team, review; next';state.events[0].notes='é'.repeat(200);var exportText='';download=(text)=>{exportText=text};ics()");const text=a.run('exportText');assert.ok(text.startsWith('BEGIN:VCALENDAR\r\n'));assert.equal((text.match(/BEGIN:VEVENT/g)||[]).length,a.run('state.events.length'));assert.ok(text.includes('SUMMARY:Team\\, review\\; next'));for(const line of text.split('\r\n'))assert.ok(Buffer.byteLength(line)<=75);assert.ok(text.includes('DTSTART:'));assert.ok(text.endsWith('END:VCALENDAR\r\n'))});


test('learning demo never overwrites the existing personal workspace',()=>{const saved=makeSeed();saved.settings.name='Personal team';const original=JSON.stringify(saved),a=app(original,false,'demo');assert.equal(a.run('mode'),'demo');a.run("move('P-102','In review')");assert.equal(a.store.get('codedfemale-product-studio-v1'),original);assert.ok(a.store.has('codedfemale-product-studio-demo-v1'));a.run("switchMode('personal')");assert.equal(a.run('state.settings.name'),'Personal team');a.run("switchMode('demo')");assert.equal(a.run("state.items.find(i=>i.id==='P-102').status"),'In review')});
test('every selected example item supports the current booking outcome',()=>{const s=makeSeed();for(const i of s.items.filter(i=>i.sprint))assert.equal(i.outcome,'Help learners book with confidence');assert.equal(s.items.find(i=>i.id==='P-108').sprint,false)});
test('learning checks require the requested action as well as a useful choice',()=>{const a=app(null,false,'demo');for(let i=0;i<7;i++){assert.equal(a.run(`exerciseResult(${i},state,learning).ok`),false);a.run(`learning.answers[LESSONS[${i}].id]=LESSONS[${i}].answer;learning.selfReview[LESSONS[${i}].id]=[0,1,2]`);assert.equal(a.run(`exerciseResult(${i},state,learning).ok`),false)}a.run("learning.reviewed.push('direction','evidence')");assert.equal(a.run('exerciseResult(0,state,learning).ok'),true);assert.equal(a.run('exerciseResult(1,state,learning).ok'),true);a.run("state.items.find(i=>i.id==='P-110').acceptance+=' Works with a keyboard.'");assert.equal(a.run('exerciseResult(2,state,learning).ok'),true);a.run("state.settings.sprintGoal='Make the booking time and confirmation easier to understand.'");assert.equal(a.run('exerciseResult(3,state,learning).ok'),true);a.run("state.items.find(i=>i.id==='P-102').blocker='';state.items.find(i=>i.id==='P-102').status='In review'");assert.equal(a.run('exerciseResult(4,state,learning).ok'),true);a.run("state.records.find(r=>r.id==='E-3').description='55% completion, with more mobile confusion. Check the tracking and period.'");assert.equal(a.run('exerciseResult(5,state,learning).ok'),false);a.run("state.records.find(r=>r.id==='E-6').description='Maya will prioritise investigating the mobile booking confusion before expanding the release.'");assert.equal(a.run('exerciseResult(5,state,learning).ok'),true);a.run("state.records.find(r=>r.id==='E-11').description='Alex will review one item each afternoon for a Sprint and discuss waiting time at the retrospective.'");assert.equal(a.run('exerciseResult(6,state,learning).ok'),true)});
test('missing practice records produce useful failure rather than a crash',()=>{const a=app(null,false,'demo');a.run("learning.answers.refine=0;state.items=[]");assert.equal(a.run('exerciseResult(2,state,learning).ok'),false);a.run("learning.answers.review=1;state.records=[]");assert.equal(a.run('exerciseResult(5,state,learning).ok'),false)});
