test('external workspace changes pause saving and preserve both copies',()=>{const a=app(null,false,'demo');a.run("state.settings.name='Local draft';save()");const other=makeSeed();other.settings.name='Other tab';a.store.set('codedfemale-product-studio-demo-v1',JSON.stringify(other));a.run("handleStorageUpdate({key:DEMO_KEY,newValue:'changed'});state.settings.name='More local edits';save()");assert.equal(a.run('externalChange'),true);assert.equal(JSON.parse(a.store.get('codedfemale-product-studio-demo-v1')).settings.name,'Other tab');a.run('reviewSavedCopy()');assert.equal(a.run('loadSavedCopy()'),true);assert.equal(a.run('state.settings.name'),'Other tab');assert.equal(JSON.parse(a.run('undoState')).settings.name,'More local edits')});
