test('priority review requires reasoning and explicit application, keeping delivery fields unchanged',()=>{const a=app(null,false,'demo');a.run('reviewPriorityOrder()');assert.equal(a.run('pendingPriorityOrder'),null);a.run("state.prioritisation.reason='Focus on the clearest booking needs while evidence is gathered.';state.prioritisation.owner='Maya';save()");const before=a.run('JSON.stringify(state.items.map(i=>({id:i.id,status:i.status,sprint:i.sprint})))'),order=a.run('JSON.stringify(state.items.map(i=>i.id))');a.run('reviewPriorityOrder()');assert.equal(a.run('JSON.stringify(state.items.map(i=>i.id))'),order);assert.equal(a.run('applyPriorityOrder()'),true);assert.equal(a.run("state.records.at(-1).title"),'Backlog order reviewed');const after=JSON.parse(a.run('JSON.stringify(state.items.map(i=>({id:i.id,status:i.status,sprint:i.sprint})))')).sort((a,b)=>a.id.localeCompare(b.id));assert.deepEqual(after,JSON.parse(before).sort((a,b)=>a.id.localeCompare(b.id)));a.run('undoLastChange()');assert.equal(a.run('JSON.stringify(state.items.map(i=>i.id))'),order)});
test('stale prioritisation reviews are refused',()=>{const a=app();a.run("state.prioritisation.reason='A reason long enough to review this example.';state.prioritisation.owner='Maya';reviewPriorityOrder();state.prioritisation.weights.impact=5");assert.equal(a.run('applyPriorityOrder()'),false)});
test('new demo examples are additive and idempotent for older saved demos',()=>{const a=app(null,false,'demo');a.run("delete state.toolsVersion;delete state.feedback;delete state.prioritisation;state.items=state.items.filter(i=>i.id!=='P-111');for(const i of state.items){delete i.dependencies;delete i.checklist;delete i.workType}state.items[0].title='Keep my edited title';addDemoToolExamples()");assert.equal(a.run('state.items[0].title'),'Keep my edited title');assert.equal(a.run('state.items.length'),11);assert.equal(a.run('state.feedback.length'),3);assert.equal(a.run('validate(state)'),true);const before=a.run('JSON.stringify(state)');a.run('addDemoToolExamples()');assert.equal(a.run('JSON.stringify(state)'),before)});
test('templates have distinct purposes and item checklists stay bounded',()=>{const a=app();for(const id of ['blank','story','bug','research','experiment'])assert.ok(a.run(`ITEM_TEMPLATES['${id}'].label`));assert.ok(a.run('ITEM_TEMPLATES.bug.description').includes('Steps to reproduce'));assert.ok(a.run('ITEM_TEMPLATES.research.description').includes('Decision this will inform'));assert.ok(a.run('ITEM_TEMPLATES.experiment.description').includes('Owner and review'));assert.equal(a.run('MEETING_TEMPLATES.review.title'),'Sprint review')});

 test('auxiliary action buttons never submit an editor form',()=>{const a=app();assert.match(a.run("btn('Add step','checklist-add')"),/type="button"/);assert.doesNotMatch(a.run("itemExtras(state.items[0])"),/<button(?![^>]*type="button")[^>]*data-action="checklist-add"/)});

test('priority movement and factor breakdown match the suggested order',()=>{const a=app();assert.equal(a.run('priorityMovement(4,1)'), 'Current 4 → suggested 1 · up 3');assert.match(a.run("priorityBreakdown(state.items.find(i=>i.id==='P-110'),state.prioritisation)"),/2.28/);assert.match(a.run('prioritisation()'),/Current 4 → suggested 1/);assert.match(a.run("priorityBreakdown(state.items[0],null)"),/Rate all four/)});
test('backlog makes prerequisite waiting and checklist progress visible',()=>{const a=app();assert.match(a.run("view='backlog';backlog()"),/Waiting on P-102, P-103/);assert.match(a.run('backlog()'),/checklist steps recorded/)});
test('meeting follow-ups save once and remain valid through removal',()=>{const a=app();a.run("linkMeetingFollowUp(state,state.events[0].id,'items','P-102');linkMeetingFollowUp(state,state.events[0].id,'items','P-102')");assert.equal(a.run('state.events[0].followUps.length'),1);assert.equal(a.run('validate(state)'),true);assert.match(a.run('meetingLinksHTML(state.events[0])'),/Make booking times clear/);assert.match(a.run("meetingSourceHTML('items','P-102')"),/Sprint planning/);a.run("pruneMeetingReferences(state,'items','P-102')");assert.equal(a.run('state.events[0].followUps.length'),0)});
test('meeting references reject missing work, unsupported collections and duplicates',()=>{for(const links of [[{type:'items',id:'missing'}],[{type:'events',id:'M-1'}],[{type:'items',id:'P-102'},{type:'items',id:'P-102'}]]){const a=app();assert.throws(()=>a.run('state.events[0].followUps='+JSON.stringify(links)+';validate(state)'))}const a=app();assert.throws(()=>a.run("linkMeetingFollowUp(state,'missing','items','P-102')"))});
test('connected exercise validates progress and requires answers plus reflection',()=>{const a=app();assert.equal(a.run('validConnected(undefined)'),true);assert.equal(a.run("connectedReady(connectedState())"),false);a.run("learning.connected={active:true,step:3,answers:{0:1,1:2,2:0,3:1},reflection:'Keep evidence, work and review decisions linked.',complete:true}");assert.equal(a.run('validProgress(learning)'),true);assert.equal(a.run('connectedReady(learning.connected)'),true);assert.match(a.run('connectedNotes()'),/Keep evidence/);a.run('learning.connected.answers[0]=0');assert.equal(a.run('validProgress(learning)'),false)});
test('connected exercise cannot silently change team records',()=>{const a=app(null,false,'demo'),before=a.run('JSON.stringify(state)');a.run("refinementAction('connected-start',{});refinementChange({target:{name:'connected-answer',value:'1'}});refinementAction('connected-next',{})");assert.equal(a.run('JSON.stringify(state)'),before);assert.equal(a.run('learning.connected.step'),1);assert.equal(a.run('validProgress(learning)'),true)});

