test('workspace find searches all record types, nested checklists and multiple words',()=>{const a=app();a.run("state.items[0].checklist=[{id:'c1',text:'Orchid release check',done:false}];state.events[0].notes='orchid release notes';state.records[0].description='orchid release decision';state.outcomes[0].evidence='orchid release evidence';state.feedback[0].observation='orchid release interview'");const hits=JSON.parse(a.run("JSON.stringify(workspaceMatches('ORCHID release'))"));assert.equal(hits.length,5);assert.deepEqual(new Set(hits.map(h=>h.type)),new Set(['items','events','records','outcomes','feedback']));assert.equal(a.run("workspaceMatches('release orchid','events').length"),1);assert.equal(a.run("workspaceMatches('orchid absent').length"),0);assert.equal(a.run("workspaceMatches('   ').length"),0)});
