test('quiet focus flags targets by local day, waiting work and missing owners while excluding Done',()=>{const a=app();a.run("state=makeSeed('2026-11-04');state.items.forEach(i=>{i.blocker='';i.dependencies=[];i.owner='Alex';i.due='';i.status='Backlog'});state.items[0].due='2026-11-03';state.items[1].due='2026-11-04';state.items[2].due='2026-11-11';state.items[3].due='2026-11-12';state.items[4].owner='';state.items[5].blocker='Needs access';state.items[6].dependencies=[state.items[7].id];state.items[8].due='2026-11-01';state.items[8].status='Done'");assert.equal(a.run("focusItems('*','attention',state,'2026-11-04').length"),6);assert.equal(a.run("focusReasons(state.items[0],'2026-11-04')[0]"),'Target date passed');assert.equal(a.run("focusReasons(state.items[1],'2026-11-04')[0]"),'Target date within 7 days');assert.equal(a.run("focusReasons(state.items[8],'2026-11-04').length"),0);assert.equal(a.run("focusItems('unassigned','active',state,'2026-11-04').length"),1);assert.equal(a.run("focusItems('owner:Alex','active',state,'2026-11-04').length"),9)});
test('focus and layout preferences do not mutate records and stay separate by mode',()=>{const a=app();const before=a.run('JSON.stringify(state)');a.run("clarityChange({target:{id:'focus-person',value:'owner:Alex'}});clarityChange({target:{id:'focus-scope',value:'sprint'}});clarityChange({target:{id:'delivery-layout',value:'list'}})");assert.equal(a.run('JSON.stringify(state)'),before);a.run("switchMode('demo')");assert.equal(a.run('clarityPreferences[mode].layout'),'auto');assert.equal(a.run('clarityPreferences[mode].person'),'*');a.run("switchMode('personal')");assert.equal(a.run('clarityPreferences[mode].layout'),'list');assert.equal(a.run('clarityPreferences[mode].person'),'owner:Alex')});
test('delivery layouts use one set of real cards, filters and movement controls',()=>{const a=app();a.run("view='delivery';clarityPreferences[mode].layout='list';owner='Alex'");const html=a.run('delivery()');assert.ok(html.includes('data-layout="list"'));const ids=JSON.parse(a.run("JSON.stringify(filtered().filter(i=>i.sprint).map(i=>i.id))"));assert.ok(ids.length);for(const id of ids)assert.equal((html.match(new RegExp('data-move="'+id+'"','g'))||[]).length,1);assert.ok(!html.includes('delivery-list-item'));assert.ok(html.includes('Move item'))});
test('spreadsheet cells preserve delimiters, quotes, line breaks and Unicode',()=>{const a=app();assert.equal(a.run('csvCell('+JSON.stringify('café, "review"\nnext')+')'),'"café, ""review""\nnext"');assert.equal(a.run('csvCell(null)'),'""');assert.equal(a.run('csvCell(false)'),'"false"');assert.equal(a.run('csvCell(0)'),'"0"');assert.equal(a.run('csvCell(["P-102","P-103"])'),'"[""P-102"",""P-103""]"')});
test('spreadsheet export neutralises formula prefixes including whitespace and full-width characters',()=>{const a=app();for(const value of ['=1+1','+SUM(1)','-1+2','@SUM(1)','  =1+1','\tdata','\rdata','\ndata','＝1+1','＋1','－1','＠SUM(1)'])assert.equal(a.run('csvCell('+JSON.stringify(value)+')'), '"\''+value+'"');assert.equal(a.run('csvCell("ordinary text")'),'"ordinary text"')});
test('CSV exports all records independently of current filters, with headers for empty collections',()=>{const a=app();a.run("view='backlog';query='no matching item';owner='Nobody';priority='Could';state.items[0].status='Done'");const before=a.run('JSON.stringify(state)');const csv=a.run("workspaceCSV('items')");assert.ok(csv.startsWith('\uFEFF"id","title"'));for(const id of JSON.parse(a.run('JSON.stringify(state.items.map(i=>i.id))')))assert.ok(csv.includes('"'+id+'"'));a.run('state.feedback=[]');assert.equal(a.run("workspaceCSV('feedback').split('\\r\\n').length"),2);assert.throws(()=>a.run("workspaceCSV('invalid')"));a.run("state=JSON.parse("+JSON.stringify(before)+")");a.run("workspaceCSV('events')");assert.equal(a.run('JSON.stringify(state)'),before)});


