test('first personal workspace starts empty with no demo assumptions',()=>{const a=app(null,false,'personal',null,false);for(const key of ['items','outcomes','events','records','feedback'])assert.equal(a.run('state.'+key+'.length'),0);assert.equal(a.run('validate(state)'),true);assert.equal(a.run('state.settings.name'),'My product workspace');assert.equal(a.run('state.settings.goal'),'');assert.equal(a.run('state.settings.sprintGoal'),'');assert.ok(a.run('overview()').includes('Add your first work item'))});
test('first personal route preserves demo and learning data and keeps reload defaults empty',()=>{const a=app(null,false,'demo');const seed=a.run('JSON.stringify(state)'),learning=a.run('JSON.stringify(learning)');a.run("save();openPersonalWorkspace()");assert.equal(a.run('mode'),'personal');assert.equal(a.run('state.events.length'),0);assert.equal(a.store.get('codedfemale-product-studio-demo-v1'),seed);assert.equal(a.run('JSON.stringify(learning)'),learning);a.run("switchMode('demo')");assert.equal(a.run('JSON.stringify(state)'),seed)});
