test('explicit blank reset is personal-only, undoable and blocked during recovery/conflict',()=>{const a=app();const before=a.run('JSON.stringify(state)');assert.equal(a.run('clearPersonalWorkspace()'),true);assert.equal(a.run('state.items.length'),0);a.run('undoLastChange()');assert.equal(a.run('JSON.stringify(state)'),before);a.run('externalChange=true');assert.equal(a.run('clearPersonalWorkspace()'),false);assert.equal(a.run('JSON.stringify(state)'),before);a.run("externalChange=false;switchMode('demo')");assert.equal(a.run('clearPersonalWorkspace()'),false);assert.equal(a.run('state.items.length'),11)});
test('calendar copy deduplication adds new source occurrences without overwriting edited copies',()=>{const a=app();a.run("var copy={...state.events[0],calendarImport:{key:'a'.repeat(64),source:'ics'}};state.events=[{...copy,title:'Local edit'}];var plan=calendarCopyPlan([copy,copy,{...copy,calendarImport:{key:'b'.repeat(64),source:'ics'}}])");assert.equal(a.run('plan.duplicates.length'),2);assert.equal(a.run('plan.newEvents.length'),1);assert.equal(a.run('state.events[0].title'),'Local edit')});
test('all-day metadata validates and exports DATE boundaries while old meetings remain valid',()=>{const a=app();a.run("state.events=[{...state.events[0],allDay:true,date:'2026-03-29',time:'00:00',duration:'1',calendarImport:{key:'a'.repeat(64),source:'ics'}}];var calendarText='';download=text=>{calendarText=text};ics()");assert.equal(a.run('validate(state)'),true);assert.ok(a.run('calendarText').includes('DTSTART;VALUE=DATE:20260329'));assert.ok(a.run('calendarText').includes('DTEND;VALUE=DATE:20260330'));a.run("calendarMonth='2026-03'");assert.ok(a.run('calendar()').includes('All day'));assert.throws(()=>a.run("state.events[0].calendarImport.key='broken';validate(state)"))});
function calendarParser(){const c=vm.createContext({Date,TextEncoder,crypto:require('node:crypto').webcrypto});vm.runInContext(fs.readFileSync(__dirname+'/vendor/ical-2.2.1.js','utf8')+'\n'+fs.readFileSync(__dirname+'/calendar-core.js','utf8'),c);return {run:s=>vm.runInContext(s,c),read:(text,from='2026-11-01',to='2026-11-30')=>vm.runInContext('readCalendarCopy('+JSON.stringify(text)+','+JSON.stringify({from,to})+')',c)}};
function calendarText(events){return 'BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Tests//EN\r\n'+events+'\r\nEND:VCALENDAR\r\n'}
function sampleEvent(extra='',uid='sample'){return 'BEGIN:VEVENT\r\nUID:'+uid+'\r\nDTSTART:20261105T090000\r\nDTEND:20261105T093000\r\nSUMMARY:Team check-in\r\n'+extra+'\r\nEND:VEVENT'}
test('calendar parser handles escaped folded text, duration, UTC and participant names',async()=>{const a=calendarParser();const text=calendarText('BEGIN:VEVENT\r\nUID:utc\r\nDTSTART:20261105T090000Z\r\nDURATION:PT45M\r\nSUMMARY:Planning\\, review\r\nDESCRIPTION:First line\\nA longer\r\n  folded line\r\nATTENDEE;CN=Alex:mailto:alex@example.test\r\nEND:VEVENT');const r=await a.read(text);assert.equal(r.events.length,1);assert.equal(r.events[0].duration,'45');assert.equal(r.events[0].title,'Planning, review');assert.equal(r.events[0].agenda,'First line\nA longer folded line');assert.equal(r.events[0].attendees,'Alex');assert.equal(r.events[0].calendarImport.key.length,64)});
test('calendar parser expands recurrence, exclusions and moved exceptions without duplicates',async()=>{const a=calendarParser();const text=calendarText(sampleEvent('RRULE:FREQ=DAILY;COUNT=4\r\nEXDATE:20261106T090000','series')+'\r\nBEGIN:VEVENT\r\nUID:series\r\nRECURRENCE-ID:20261107T090000\r\nDTSTART:20261107T110000\r\nDTEND:20261107T113000\r\nSUMMARY:Moved check-in\r\nEND:VEVENT');const r=await a.read(text);assert.equal(r.events.length,3);assert.deepEqual(Array.from(r.events,e=>e.date),['2026-11-05','2026-11-07','2026-11-08']);assert.equal(r.events[1].time,'11:00');assert.equal(new Set(r.events.map(e=>e.calendarImport.key)).size,3)});
test('calendar parser handles all-day spans through a daylight-saving change',async()=>{const a=calendarParser();const r=await a.read(calendarText('BEGIN:VEVENT\r\nUID:away\r\nDTSTART;VALUE=DATE:20260328\r\nDTEND;VALUE=DATE:20260331\r\nSUMMARY:Team away\r\nEND:VEVENT'),'2026-03-01','2026-04-01');assert.deepEqual(Array.from(r.events,e=>e.date),['2026-03-28','2026-03-29','2026-03-30']);assert.ok(r.events.every(e=>e.allDay));assert.equal(new Set(r.events.map(e=>e.calendarImport.key)).size,3)});
test('calendar parser reports unknown timezones and unsupported long or cancelled meetings',async()=>{const a=calendarParser();const text=calendarText(sampleEvent('STATUS:CANCELLED','cancel')+'\r\n'+sampleEvent('','long').replace('DTEND:20261105T093000','DTEND:20261105T190000')+'\r\n'+sampleEvent('','unknown').replace('DTSTART:','DTSTART;TZID=MISSING/ZONE:'));const r=await a.read(text);assert.equal(r.events.length,0);assert.equal(r.skippedCount,3);assert.ok(r.skipped.some(s=>s.includes('MISSING/ZONE')))});
test('calendar parser rejects invalid files/ranges and caps frequent repeating events',async()=>{const a=calendarParser();await assert.rejects(a.read('not a calendar'));await assert.rejects(a.read(calendarText(sampleEvent()),'2026-02-30','2026-03-02'));await assert.rejects(a.read(calendarText(sampleEvent()),'2026-01-01','2026-12-31'));const r=await a.read(calendarText(sampleEvent('RRULE:FREQ=MINUTELY;COUNT=10000')));assert.equal(r.events.length,300);assert.ok(r.warnings.some(s=>s.includes('limited to 300')))});
test('calendar parser converts an embedded timezone definition to the device local time',async()=>{const a=calendarParser();const zone='BEGIN:VTIMEZONE\r\nTZID:Custom/Eastern\r\nBEGIN:STANDARD\r\nDTSTART:19700101T000000\r\nTZOFFSETFROM:-0500\r\nTZOFFSETTO:-0500\r\nEND:STANDARD\r\nEND:VTIMEZONE';const event=sampleEvent('','zoned').replace('DTSTART:','DTSTART;TZID=Custom/Eastern:').replace('DTEND:','DTEND;TZID=Custom/Eastern:');const r=await a.read(calendarText(zone+'\r\n'+event));assert.equal(r.events.length,1);assert.equal(r.skippedCount,0);const local=new Date('2026-11-05T14:00:00Z');assert.equal(r.events[0].time,String(local.getHours()).padStart(2,'0')+':00')});


test('source rescheduling does not create another copy of an already identified single event',async()=>{const a=calendarParser();const first=await a.read(calendarText(sampleEvent('','stable')));const later=await a.read(calendarText(sampleEvent('','stable').replaceAll('20261105T09','20261106T09').replace('Team check-in','Renamed meeting')));assert.equal(first.events.length,1);assert.equal(later.events.length,1);assert.equal(first.events[0].calendarImport.key,later.events[0].calendarImport.key);assert.notEqual(first.events[0].date,later.events[0].date)});

function prepareEstimate(a,deck='points',value='5'){a.run("view='estimation';chooseEstimateSetting('item','P-102',true);var draftEstimate=estimateDraft();draftEstimate.deck="+JSON.stringify(deck)+";draftEstimate.value="+JSON.stringify(value)+";draftEstimate.confidence='Medium';draftEstimate.rationale='Includes implementation, cross-zone testing and review.';draftEstimate.dirty=true;")}
test('estimation is reachable from both navigation controls and an empty personal workspace',()=>{const a=app();assert.equal(a.run("navigateWorkspace('estimation')"),true);assert.ok(a.run('estimationStudio()').includes('Size the work. Share the reasoning.'));assert.ok(a.run("optionalPlanningFields(state.items[0])").includes('Open estimation studio'));const empty=app(null,false,'personal',null,false);assert.ok(empty.run('estimationStudio()').includes('Add a work item'));assert.ok(!empty.run('estimationStudio()').includes('Response 1'))});
test('numeric estimation saves a scope snapshot, updates only points and supports complete Undo',()=>{const a=app();prepareEstimate(a);const before=a.run('JSON.stringify(state)');assert.equal(a.run('saveEstimateDecision()'),true);assert.equal(a.run("state.items.find(i=>i.id==='P-102').points"),'5');assert.equal(a.run('state.estimateHistory.length'),1);assert.equal(a.run('state.estimateHistory[0].previousPoints'),'3');assert.equal(a.run('state.estimateHistory[0].rounds[0].votes[0].value'),'5');assert.equal(a.run('validate(state)'),true);assert.equal(a.run('saveEstimateDecision()'),false);a.run('undoLastChange();render()');assert.equal(a.run('JSON.stringify(state)'),before);assert.equal(a.run('estimateDraft().saved'),false);assert.equal(a.run('estimateDraft().dirty'),true);assert.equal(a.run('saveEstimateDecision()'),true)});
test('T-shirt sizes save reasoning without converting or overwriting numeric backlog points',()=>{const a=app();prepareEstimate(a,'tshirt','L');assert.equal(a.run('saveEstimateDecision()'),true);assert.equal(a.run("state.items.find(i=>i.id==='P-102').points"),'3');assert.equal(a.run('state.estimateHistory[0].value'),'L');assert.ok(a.run('estimateHistory()').includes('Numeric backlog points unchanged.'))});
test('question cards require a real question and preserve existing points',()=>{const a=app();prepareEstimate(a,'points','?');assert.equal(a.run('saveEstimateDecision()'),false);assert.equal(a.run('(state.estimateHistory||[]).length'),0);a.run("draftEstimate.uncertainty='Do we have a cross-zone test account?'");assert.equal(a.run('saveEstimateDecision()'),true);assert.equal(a.run("state.items.find(i=>i.id==='P-102').points"),'3');assert.ok(a.run('estimateHistory()').includes('Needs clarification'))});
test('group summaries handle zero and questions without selecting a mean',()=>{const a=app();a.run("var summary=estimateVoteSummary([{value:'0'},{value:'8'},{value:'?'}],'points')");assert.equal(a.run('summary.min'),0);assert.equal(a.run('summary.max'),8);assert.equal(a.run('summary.unknown'),1);assert.equal(a.run('summary.mixed'),true);assert.equal(a.run("estimateVoteSummary([{value:'S'},{value:'L'}],'tshirt').min"),null);prepareEstimate(a);a.run("draftEstimate.method='group';draftEstimate.value='';draftEstimate.responses=[{value:'3',reason:'Familiar UI'},{value:'8',reason:'Uncertain test data'}];draftEstimate.revealed=true");assert.equal(a.run('saveEstimateDecision()'),false);assert.equal(a.run("state.items.find(i=>i.id==='P-102').points"),'3');assert.equal(a.run('draftEstimate.value'),'')});
test('a facilitated decision needs two reviewed responses and retains unresolved questions',()=>{const a=app();prepareEstimate(a);a.run("draftEstimate.method='group';draftEstimate.responses=[{value:'5',reason:'Scope clear'},{value:'?',reason:'Unknown data'}]");assert.equal(a.run('saveEstimateDecision()'),false);a.run('draftEstimate.revealed=true');assert.equal(a.run('saveEstimateDecision()'),false);a.run("draftEstimate.uncertainty='Confirm whether test data is available.'");assert.equal(a.run('saveEstimateDecision()'),true);assert.equal(a.run('state.estimateHistory[0].rounds[0].votes.length'),2)});
test('another round preserves earlier responses independently and requires a fresh agreed choice',()=>{const a=app();prepareEstimate(a);a.run("draftEstimate.method='group';draftEstimate.responses=[{value:'3',reason:'UI only'},{value:'8',reason:'Extra testing'}];draftEstimate.revealed=true;estimationAction('estimate-reround',{})");assert.equal(a.run('draftEstimate.priorRounds.length'),1);assert.equal(a.run('draftEstimate.value'),'');assert.equal(a.run('draftEstimate.responses[0].value'),'');a.run("draftEstimate.responses[0].value='5';draftEstimate.responses[1].value='5';draftEstimate.responses[0].reason='Includes the tests';draftEstimate.value='5';draftEstimate.confidence='Medium';draftEstimate.revealed=true");assert.equal(a.run('saveEstimateDecision()'),true);assert.equal(a.run('state.estimateHistory[0].rounds.length'),2);assert.equal(a.run('state.estimateHistory[0].rounds[0].votes[0].value'),'3');assert.equal(a.run('state.estimateHistory[0].rounds[1].votes[0].value'),'5')});
test('changed or deleted scope prevents an old round from overwriting work',()=>{const a=app();prepareEstimate(a);a.run("state.items.find(i=>i.id==='P-102').acceptance='Scope has changed'");assert.equal(a.run('saveEstimateDecision()'),false);assert.equal(a.run('(state.estimateHistory||[]).length'),0);assert.equal(a.run("state.items.find(i=>i.id==='P-102').points"),'3');a.run("state.items=state.items.filter(i=>i.id!=='P-102')");assert.equal(a.run('saveEstimateDecision()'),false)});
test('estimation drafts and recorded decisions remain separate between workspaces',()=>{const a=app();prepareEstimate(a);a.run('saveEstimateDecision()');a.run("switchMode('demo')");assert.equal(a.run('(state.estimateHistory||[]).length'),0);assert.equal(a.run("state.items.find(i=>i.id==='P-102').points"),'3');a.run("switchMode('personal')");assert.equal(a.run('state.estimateHistory.length'),1);assert.equal(a.run('estimateDraft().value'),'5');a.run('clearPersonalWorkspace()');assert.equal(a.run('estimationDrafts.personal'),null)});
test('changing deck or work asks before discarding an unsaved round',()=>{const a=app();prepareEstimate(a);a.run("chooseEstimateSetting('deck','tshirt')");assert.equal(a.run('estimateDraft().deck'),'points');assert.equal(a.nodes.get('#editor').open,true);a.run("chooseEstimateSetting('deck','tshirt',true)");assert.equal(a.run('estimateDraft().deck'),'tshirt');assert.equal(a.run('estimateDraft().value'),'');assert.equal(a.run('estimateDraft().dirty'),false)});
test('history validates older backups and rejects invalid estimates, votes and duplicate entries',()=>{const a=app();assert.equal(a.run('validate(state)'),true);prepareEstimate(a);a.run('saveEstimateDecision()');const good=a.run('JSON.stringify(state)');for(const mutation of ["s.estimateHistory[0].deck='hours'","s.estimateHistory[0].value='-5'","s.estimateHistory[0].scope.dependencies=['bad id']","s.estimateHistory[0].rounds[0].votes[0].value='13'","s.estimateHistory.push(s.estimateHistory[0])","s.estimateHistory[0].confidence='Certain'","s.estimateHistory[0].rationale=''","s.estimateHistory[0].savedAt='not a date'"]){assert.throws(()=>a.run("(()=>{var s=JSON.parse("+JSON.stringify(good)+");"+mutation+";validate(s)})()"))}});
test('estimation brief includes scope and choices but omits the current points to reduce anchoring',()=>{const a=app();a.run("state.items.find(i=>i.id==='P-102').points='999'");prepareEstimate(a);const brief=a.run('estimationBrief()');assert.ok(brief.includes('P-102'));assert.ok(brief.includes('Acceptance criteria'));assert.ok(brief.includes('not a live voting room'));assert.ok(!brief.includes('999'))});
test('history and CSV escape typed content and retain scope after an item is deleted',()=>{const a=app();prepareEstimate(a);a.run("draftEstimate.rationale='<img src=x onerror=alert(1)> is not executed';saveEstimateDecision();state.items=state.items.filter(i=>i.id!=='P-102')");const html=a.run('estimateHistory()');assert.ok(html.includes('&lt;img'));assert.ok(!html.includes('<img'));assert.ok(a.run('estimationCSV()').includes('P-102'));assert.ok(a.run('estimationCSV()').includes('daylight saving'));assert.equal(a.run('validateEstimationHistory(state)'),undefined)});
test('refreshing a completed or removed item offers an active alternative without losing saved history',()=>{const a=app();prepareEstimate(a);a.run("draftEstimate.dirty=false;state.items.find(i=>i.id==='P-102').status='Done';estimationAction('estimate-refresh',{})");assert.notEqual(a.run('estimateDraft().itemId'),'P-102');a.run("state.items.forEach(i=>{i.status='Done'});estimateDraft().dirty=false;estimationAction('estimate-refresh',{})");assert.equal(a.run('estimateDraft()'),null);assert.ok(a.run('estimationStudio()').includes('Add a work item'))});


test('clearing history preserves backlog points, leaves unfinished rounds and can be undone',()=>{const a=app();prepareEstimate(a);a.run('saveEstimateDecision()');const before=a.run('JSON.stringify(state)');a.run("draftEstimate.rationale='Unfinished follow-up reasoning';draftEstimate.dirty=true;clearEstimateHistory()");assert.equal(a.run('state.estimateHistory.length'),0);assert.equal(a.run("state.items.find(i=>i.id==='P-102').points"),'5');assert.equal(a.run('estimateDraft().rationale'),'Unfinished follow-up reasoning');a.run('undoLastChange()');assert.equal(a.run('JSON.stringify(state)'),before)});

test('unrelated typing and controls do not initialise an estimation round',()=>{const a=app();assert.equal(a.run('estimationDrafts.personal'),null);assert.equal(a.run("estimationInput({target:{dataset:{},name:'title',value:'New title'}})"),false);assert.equal(a.run("estimationChange({target:{dataset:{},id:'owner',value:'Alex'}})"),false);assert.equal(a.run('estimationDrafts.personal'),null)});
test('saved work views retain filters, scope and layout without changing work',()=>{const a=app();a.run("view='delivery';query='booking';owner='Alex';priority='Must';clarityPreferences.personal.layout='list'");const items=a.run('JSON.stringify(state.items)');a.run("saveWorkView('Booking focus');query='';owner='All';priority='All';clarityPreferences.personal.layout='board';applyWorkView(state.savedWorkViews[0].id)");assert.equal(a.run('view'),'delivery');assert.equal(a.run('query'),'booking');assert.equal(a.run('owner'),'Alex');assert.equal(a.run('priority'),'Must');assert.equal(a.run('clarityPreferences.personal.layout'),'list');assert.equal(a.run('JSON.stringify(state.items)'),items);assert.equal(a.run('validate(state)'),true)});
test('saved views persist in workspace storage and stay separate between modes',()=>{const a=app();a.run("view='backlog';backlogScope='completed';saveWorkView('Completed work review')");const original=a.store.get('codedfemale-product-studio-v1'),b=app(original);assert.equal(b.run('state.savedWorkViews[0].scope'),'completed');a.run("switchMode('demo')");assert.equal(a.run('(state.savedWorkViews||[]).length'),0);a.run("switchMode('personal')");assert.equal(a.run('state.savedWorkViews.length'),1)});
test('saved view validation rejects duplicates, oversized and invalid shortcuts',()=>{const a=app();a.run("saveWorkView('Team focus')");assert.throws(()=>a.run("saveWorkView('team FOCUS')"));assert.throws(()=>a.run("saveWorkView('')"));const original=a.run('JSON.stringify(state)');for(const change of ["s.savedWorkViews[0].scope='everything'","s.savedWorkViews[0].view='unknown'","s.savedWorkViews[0].priority='urgent'","s.savedWorkViews[0].query='a'.repeat(201)","s.savedWorkViews[0].layout='invalid'","s.savedWorkViews.push(s.savedWorkViews[0])"]){assert.throws(()=>a.run("(()=>{let s=JSON.parse("+JSON.stringify(original)+");"+change+";validate(s)})()"))}});
test('removing a saved shortcut keeps work and is undoable',()=>{const a=app();a.run("saveWorkView('My queue')");const before=a.run('JSON.stringify(state)');a.run('removeWorkView(state.savedWorkViews[0].id)');assert.equal(a.run('state.savedWorkViews.length'),0);assert.equal(a.run('state.items.length'),11);a.run('undoLastChange()');assert.equal(a.run('JSON.stringify(state)'),before)});
test('bulk preview changes selected owners, priorities and dates without mutating source or protected fields',()=>{const a=app();const before=a.run('JSON.stringify(state)');a.run("var plan=buildBulkWorkPlan(state,['P-102','P-103'],{ownerMode:'set',owner:'Maya',priority:'Should',dateMode:'shift',days:'5'})");assert.equal(a.run('JSON.stringify(state)'),before);assert.equal(a.run('plan.changes.length'),2);assert.equal(a.run("plan.draft.items.find(i=>i.id==='P-102').owner"),'Maya');assert.equal(a.run("plan.draft.items.find(i=>i.id==='P-102').due"),a.run("dateOffset(state.items.find(i=>i.id==='P-102').due,5)"));for(const field of ['status','points','sprint','acceptance','dependencies','checklist'])assert.equal(a.run("JSON.stringify(plan.draft.items.find(i=>i.id==='P-102')."+field+")"),a.run("JSON.stringify(state.items.find(i=>i.id==='P-102')."+field+")"));assert.equal(a.run("JSON.stringify(plan.draft.items.find(i=>i.id==='P-105'))"),a.run("JSON.stringify(state.items.find(i=>i.id==='P-105'))"))});
test('bulk date shifts preserve missing dates and calendar-day semantics through clock changes',()=>{const a=app();a.run("state.items.find(i=>i.id==='P-102').due='2026-03-28';state.items.find(i=>i.id==='P-103').due='';var plan=buildBulkWorkPlan(state,['P-102','P-103'],{ownerMode:'keep',priority:'keep',dateMode:'shift',days:'2'})");assert.equal(a.run('plan.undated'),1);assert.equal(a.run('plan.unchanged'),1);assert.equal(a.run("plan.draft.items.find(i=>i.id==='P-102').due"),'2026-03-30');assert.equal(a.run("plan.draft.items.find(i=>i.id==='P-103').due"),'')});
test('bulk planning rejects completed, hidden, duplicate or absent items and invalid/no-op changes',()=>{const a=app();for(const input of ["buildBulkWorkPlan(state,[],{ownerMode:'clear',priority:'keep',dateMode:'keep'})","buildBulkWorkPlan(state,['P-104'],{ownerMode:'clear',priority:'keep',dateMode:'keep'})","buildBulkWorkPlan(state,['P-102'],{ownerMode:'clear',priority:'keep',dateMode:'keep'},['P-103'])","buildBulkWorkPlan(state,['P-102','P-102'],{ownerMode:'clear',priority:'keep',dateMode:'keep'})","buildBulkWorkPlan(state,['P-102'],{ownerMode:'set',owner:' ',priority:'keep',dateMode:'keep'})","buildBulkWorkPlan(state,['P-102'],{ownerMode:'keep',priority:'keep',dateMode:'set',date:'2026-02-30'})","buildBulkWorkPlan(state,['P-102'],{ownerMode:'keep',priority:'keep',dateMode:'shift',days:'1.5'})","buildBulkWorkPlan(state,['P-102'],{ownerMode:'keep',priority:'keep',dateMode:'shift',days:'366'})","buildBulkWorkPlan(state,['P-102'],{ownerMode:'keep',priority:'keep',dateMode:'keep'})"]){assert.throws(()=>a.run(input))}});
test('bulk application is one undoable change and refuses stale or cross-mode previews',()=>{const a=app();const before=a.run('JSON.stringify(state)');a.run("view='backlog';var plan=buildBulkWorkPlan(state,['P-102','P-103'],{ownerMode:'set',owner:'Maya',priority:'keep',dateMode:'keep'});pendingBulkWork={...plan,mode,base:JSON.stringify(state)}");assert.equal(a.run('applyBulkWork()'),true);assert.equal(a.run("state.items.find(i=>i.id==='P-102').owner"),'Maya');a.run('undoLastChange()');assert.equal(a.run('JSON.stringify(state)'),before);a.run("pendingBulkWork={...plan,mode,base:JSON.stringify(state)};state.settings.name='Changed elsewhere'");assert.equal(a.run('applyBulkWork()'),false);a.run("pendingBulkWork={...plan,mode:'demo',base:JSON.stringify(state)}");assert.equal(a.run('applyBulkWork()'),false)});
test('saved-item visibility notices explain hidden filters and can reveal completed or unsprinted work',()=>{const a=app();a.run("view='backlog';owner='Maya';noteWorkChange(['P-102'],'Saved')");assert.ok(a.run('workVisibilityNotice()').includes('not shown in this view'));assert.equal(a.run('owner'),'Maya');a.run('showSavedWork()');assert.equal(a.run('owner'),'All');assert.equal(a.run('view'),'backlog');a.run("state.items.find(i=>i.id==='P-104').status='Done';backlogScope='active';noteWorkChange(['P-104'])");assert.ok(a.run('workVisibilityNotice()').includes('Show saved work'));a.run('showSavedWork()');assert.equal(a.run('backlogScope'),'completed');a.run("view='delivery';noteWorkChange(['P-109'])");assert.ok(a.run('workVisibilityNotice()').includes('Sprint selection'))});
test('bulk selection in delivery is restricted to rendered Sprint stages and visibility notices stay local',()=>{const a=app();a.run("view='delivery';query='';owner='All';priority='All'");assert.ok(a.run("bulkCandidates().every(i=>i.sprint&&i.status!=='Done'&&STAGES.includes(i.status))"));a.run("noteWorkChange(['P-109']);switchMode('demo')");assert.equal(a.run('recentWorkEdits.demo'),null);assert.equal(a.run('workVisibilityNotice()'),'')});
test('edited forms protect close controls outside the form while allowing true submits and selection helpers',()=>{const a=app();let guard; a.c.document.addEventListener=(type,fn,capture)=>{if(type==='click'&&capture===true)guard=fn};a.run("installEditorProtection();var exitWarnings=0;var guardedForm={};editorDirty=()=>true;editableForm=()=>guardedForm;askEditorExit=()=>{exitWarnings++}");let stopped=0;const click=b=>guard({target:{closest:()=>b},preventDefault(){stopped++},stopImmediatePropagation(){}});click({type:'submit',form:null,dataset:{action:'close'}});assert.equal(a.run('exitWarnings'),1);assert.equal(stopped,1);click({type:'submit',form:a.run('guardedForm'),dataset:{}});assert.equal(a.run('exitWarnings'),1);click({type:'button',form:null,dataset:{action:'bulk-work-select'}});assert.equal(a.run('exitWarnings'),1)});
test('bulk updates handle an entire 500-item selection without a small multi-select cap',()=>{const a=app();a.run("var source=makeBlankWorkspace('2026-11-06');var template=makeSeed().items.find(i=>i.id==='P-102');source.items=Array.from({length:500},(_,n)=>({...template,id:'P-'+(1000+n),title:'Work '+n,status:'Backlog',sprint:false,outcome:'',dependencies:[],checklist:[]}));var plan=buildBulkWorkPlan(source,source.items.map(i=>i.id),{ownerMode:'set',owner:'Maya',priority:'keep',dateMode:'keep'})");assert.equal(a.run('plan.changes.length'),500);assert.equal(a.run('plan.draft.items.every(i=>i.owner===\'Maya\')'),true);assert.equal(a.run('source.items.every(i=>i.owner===\'Alex\')'),true);assert.equal(a.run('validate(plan.draft)'),true)});
test('saved view names render as text rather than markup',()=>{const a=app();a.run("view='backlog';saveWorkView('<img src=x onerror=alert(1)>')");const html=a.run('workTools()');assert.ok(html.includes('&lt;img'));assert.ok(!html.includes('<img src=x'))});
test('opening a saved backlog view leaves the independent delivery layout choice alone',()=>{const a=app();a.run("view='backlog';saveWorkView('Backlog focus');clarityPreferences.personal.layout='list';applyWorkView(state.savedWorkViews[0].id)");assert.equal(a.run('clarityPreferences.personal.layout'),'list')});
test('first personal overview prioritises setup without empty statistics and duplicate panels',()=>{const a=app(null,false,'personal',null,false);const html=a.run('overview()');assert.ok(html.includes('Your workspace starts here.'));assert.ok(html.includes('Set up your workspace'));assert.ok(html.includes('Add your first work item'));assert.ok(!html.includes('items Done'));assert.ok(!html.includes('What needs a conversation?'));a.run("state.settings.goal='Improve the first-use experience'");assert.ok(a.run('overview()').includes('Improve the first-use experience'));a.run("state.items=[{...makeSeed().items[0],outcome:'',dependencies:[],sprint:false}]");assert.ok(a.run('overview()').includes('What needs a conversation?'))});
test('opening the personal workspace returns to the top so mode and save controls remain visible',()=>{const a=app(null,false,'demo');let scroll;a.c.window.scrollTo=options=>{scroll=options};a.run('openPersonalWorkspace()');assert.equal(a.run('mode'),'personal');assert.equal(scroll.top,0);assert.equal(a.run('isEmptyPersonalWorkspace()'),true)});
